package com.hms.appointments;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.hms.doctors.*; import com.hms.tenancy.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class AppointmentLifecycleTests { @Autowired MockMvc mockMvc; @Autowired TenantRepository tenants; @Autowired DoctorRepository doctors; @Autowired AppointmentRepository appointments; private Doctor doctor; @BeforeEach void setup(){appointments.deleteAll();doctors.deleteAll();tenants.deleteAll();Tenant t=tenants.save(new Tenant(UUID.randomUUID(),"life-care","Life Care",null,TenantStatus.ACTIVE,null,null));doctor=doctors.save(new Doctor(t.getId(),new CreateDoctorRequest("Dr. Life","General",null,null,4,null,null,true,Set.of())));} private String create() throws Exception{return mockMvc.perform(post("/api/hospitals/life-care/appointments").contentType(MediaType.APPLICATION_JSON).content("{\"fullName\":\"Test Patient\",\"phone\":\"+919999999999\",\"doctorId\":\""+doctor.getId()+"\",\"startsAt\":\"2026-09-28T09:00:00Z\",\"endsAt\":\"2026-09-28T09:20:00Z\",\"source\":\"STAFF\"}")).andReturn().getResponse().getContentAsString();} @Test void reschedulesConfirmedAppointment() throws Exception{String id=com.jayway.jsonpath.JsonPath.read(create(),"$.id");mockMvc.perform(patch("/api/hospitals/life-care/appointments/"+id+"/status").contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"CONFIRMED\"}")).andExpect(status().isOk());mockMvc.perform(patch("/api/hospitals/life-care/appointments/"+id+"/reschedule").contentType(MediaType.APPLICATION_JSON).content("{\"startsAt\":\"2026-09-28T10:00:00Z\",\"endsAt\":\"2026-09-28T10:20:00Z\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("RESCHEDULED"));} @Test void recordsPaymentStatus() throws Exception{String id=com.jayway.jsonpath.JsonPath.read(create(),"$.id");mockMvc.perform(patch("/api/hospitals/life-care/appointments/"+id+"/payment").contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"VERIFIED\",\"reference\":\"UPI-123\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.paymentStatus").value("VERIFIED"));}}
